// Saca los que traen número de guía. Sin guía no hay nada que rastrear.
const oportunidades = $input.first().json.opportunities || [];
const salida = [];

for (const o of oportunidades) {
  const campos = o.customFields || [];
  const buscar = (clave) => {
    const c = campos.find(x => (x.fieldKey || '').endsWith(clave) || x.id === clave);
    return c ? (c.fieldValue ?? c.value) : null;
  };
  const guia = buscar('numero_guia');
  if (!guia) continue;
  salida.push({ json: { opportunityId: o.id, contactId: o.contactId, numero_guia: guia } });
}
return salida;

// Traduce el estatus de Envia a las dos cosas que nos importan:
// ¿llegó a la sucursal? ¿ya lo recogieron?
const r = $json.data || $json;
const primero = Array.isArray(r) ? r[0] : r;
const eventos = primero.events || primero.history || [];
const crudo = (primero.status || (eventos[0] && eventos[0].status) || '').toString().toLowerCase();

const dice = (...palabras) => palabras.some(p => crudo.includes(p));

let estado = 'en_transito';
if (dice('delivered', 'entregado')) estado = 'entregado';
else if (dice('ready for pickup', 'disponible', 'en sucursal', 'office', 'ocurre')) estado = 'en_sucursal';

const entrada = $('Los que tienen guía').all().map(i => i.json)
  .find(x => x.numero_guia === (primero.trackingNumber || primero.tracking_number)) || {};

return [{ json: { ...entrada, estado, estado_crudo: crudo,
                  mover_a: estado === 'entregado' ? $env.GHL_STAGE_ENTREGADO : null } }];
